import{_ as a,o as i,c as t,a5 as n}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Chat extensions — confirmed scope, 2026-10-23","description":"","frontmatter":{},"headers":[],"relativePath":"feature/workspace-chat-collaboration/extension-roadmap.md","filePath":"feature/workspace-chat-collaboration/extension-roadmap.md"}'),o={name:"feature/workspace-chat-collaboration/extension-roadmap.md"};function s(r,e,l,c,d,p){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="chat-extensions-—-confirmed-scope-2026-10-23" tabindex="-1">Chat extensions — confirmed scope, 2026-10-23 <a class="header-anchor" href="#chat-extensions-—-confirmed-scope-2026-10-23" aria-label="Permalink to &quot;Chat extensions — confirmed scope, 2026-10-23&quot;">​</a></h1><h2 id="spec" tabindex="-1">Spec <a class="header-anchor" href="#spec" aria-label="Permalink to &quot;Spec&quot;">​</a></h2><p>Web first. Notify direct mentions, new DMs, invitations and missed calls; exclude the sender, respect channel access. Add mute/DND. Upload JPEG/PNG/WebP/PDF only, 5 files per message, 10 MB per file; do not debit Agency storage quota. Presence is session-based online/offline. Web Push requires opt-in and hides message text. Voice calls are DM one-to-one first. Huddles (20 participants, Client may start), video, screen sharing and external integrations are deferred. Media infrastructure requires budget approval; do not provision services automatically.</p><h2 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h2><ol start="0"><li>Align Mongo init validators with migration and preflight existing documents.</li><li>Persist identity-based mentions and durable notification events, then inbox.</li><li>Redis session TTL presence, including multiple tabs.</li><li>Private S3 uploads, type/size verification and abandoned-upload cleanup.</li><li>Opt-in Web Push with account/device isolation.</li><li>Approved media provider, voice invitation/call lifecycle and missed calls.</li></ol><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><ul><li>[x] Align schema and verify locally without applying shared databases.</li><li>[x] Confirm mute/DND inbox versus alert semantics and presence visibility.</li><li>[ ] Complete mention UI and live delivery verification (backend foundation implemented in chat-mention-inbox).</li><li>[ ] Implement presence, attachments and push in independent rollout steps.</li><li>[ ] Approve voice infrastructure before enabling real calls.</li></ul><h2 id="test" tabindex="-1">Test <a class="header-anchor" href="#test" aria-label="Permalink to &quot;Test&quot;">​</a></h2><p>Compare init/migration validators; reject invalid existing records before APPLY. Exercise access revocation, duplicate sends/events, worker retry, multi-tab expiry, private downloads, MIME/size spoofing, opt-out/logout and stale subscriptions. Run authenticated multi-user integration checks separately from mocked UI tests. No live notification, call or shared DB write is authorized by local verification.</p><h2 id="confirmed-clarification" tabindex="-1">Confirmed clarification <a class="header-anchor" href="#confirmed-clarification" aria-label="Permalink to &quot;Confirmed clarification&quot;">​</a></h2><p>Mute/DND retain inbox entries but suppress toast, sound, Web Push and ringing; muting a channel also suppresses mention alerts there. Do not automatically decline calls. Presence is Online/Offline visible within the same Workspace, no last seen, Away or invisible mode; heartbeat expiry is not a read receipt.</p>',11)])])}const m=a(o,[["render",s]]);export{h as __pageData,m as default};
